INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was versteht ein Fachinformatiker unter einer Built-in-Funktion?', 2, '[{"text": "Vorgefertigte Funktion in einer Sprache", "correct": true, "because": "Eingebaut und direkt nutzbar"}, {"text": "Benutzerdefinierte Funktion", "correct": false, "because": "Selbst erstellt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Built-in-Funktionen?', 3, '[{"text": "Code vereinfachen und Wiederverwendung fördern", "correct": true, "because": "Effizienz steigern"}, {"text": "Kosten direkt senken", "correct": false, "because": "Indirekt"}, {"text": "Design verbessern", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Built-in-Funktionen gibt es in SQL?', 5, '[{"text": "Aggregatfunktionen", "correct": true, "because": "z.B. SUM, COUNT"}, {"text": "Skalarfunktionen", "correct": true, "because": "z.B. UPPER, LENGTH"}, {"text": "Designfunktionen", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) COUNT ist eine Built-in-Funktion in SQL. b) Sie müssen vom Nutzer definiert werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Eingebaut, nicht definiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Built-in-Funktionen?', 4, '[{"text": "Funktionsaufruf", "correct": false, "because": "Nutzung wichtig"}, {"text": "Parameter", "correct": false, "because": "Einfluss auf Ergebnis"}, {"text": "Büroverschönerung", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob LENGTH eine Built-in-Funktion in SQL ist?', 2, '[{"text": "Ja", "correct": true, "because": "Zeichenlänge"}, {"text": "Nein", "correct": false, "because": "Standardfunktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Built-in-Funktion zählt Datensätze in SQL?', 3, '[{"text": "COUNT", "correct": true, "because": "Aggregatfunktion"}, {"text": "SUM", "correct": false, "because": "Addition"}, {"text": "AVG", "correct": false, "because": "Durchschnitt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Nutzung von Built-in-Funktionen?', 5, '[{"text": "Korrekte Syntax", "correct": true, "because": "Aufruf erforderlich"}, {"text": "Parameterangabe", "correct": true, "because": "Funktionsspezifisch"}, {"text": "Farbcodierung", "correct": false, "because": "Kein Bezug"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Built-in-Funktionen vereinfachen Abfragen. b) Sie sind nur in SQL verfügbar. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch andere Sprachen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Built-in-Funktionen unwichtig?', 4, '[{"text": "Rückgabewert", "correct": false, "because": "Ergebnis wichtig"}, {"text": "Parameter", "correct": false, "because": "Einfluss auf Funktion"}, {"text": "Schriftart", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss eine Built-in-Funktion definiert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Eingebaut"}, {"text": "Ja", "correct": false, "because": "Vorgefertigt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bieten Built-in-Funktionen für Fachinformatiker?', 4, '[{"text": "Zeitersparnis", "correct": true, "because": "Wiederverwendung"}, {"text": "Einfachheit", "correct": true, "because": "Weniger Code"}, {"text": "Schnellere Hardware", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Built-in-Funktionen nur für Datenbanken sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Programmierung"}, {"text": "Ja", "correct": false, "because": "Universell"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Built-in-Funktionen?', 3, '[{"text": "Korrekte Nutzung", "correct": true, "because": "Funktionalität"}, {"text": "Kosten", "correct": false, "because": "Sekundär"}, {"text": "Ästhetik", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) UPPER ist eine Built-in-Funktion in SQL. b) Sie erstellt Tabellen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Textumwandlung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile haben Built-in-Funktionen?', 5, '[{"text": "Eingeschränkte Flexibilität", "correct": true, "because": "Feste Funktion"}, {"text": "Abhängigkeit vom System", "correct": true, "because": "Verfügbarkeit"}, {"text": "Schnellere Entwicklung", "correct": false, "because": "Kein Nachteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe hat ein Fachinformatiker bei Built-in-Funktionen?', 3, '[{"text": "Effiziente Nutzung", "correct": true, "because": "Code-Optimierung"}, {"text": "Büro reinigen", "correct": false, "because": "Kein Bezug"}, {"text": "Marketing betreiben", "correct": false, "because": "Andere Aufgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine Built-in-Funktion in SQL Parameter haben?', 2, '[{"text": "Ja", "correct": true, "because": "z.B. LENGTH(name)"}, {"text": "Nein", "correct": false, "because": "Flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche SQL-Built-in-Funktion wandelt Text in Großbuchstaben um?', 4, '[{"text": "UPPER", "correct": true, "because": "Textumwandlung"}, {"text": "LOWER", "correct": false, "because": "Kleinbuchstaben"}, {"text": "COUNT", "correct": false, "because": "Zählfunktion"}]');
